// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title ImageProcessingPool
 * @notice Manages a pool of image processing jobs with signature-based authorization
 * @dev Uses connection pooling pattern for batch job submission
 */
contract ImageProcessingPool {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct ProcessingJob {
        address requester;
        bytes32 imageHash;
        uint8 filterType;
        uint256 priority;
        uint256 timestamp;
        bool completed;
    }

    struct PoolConnection {
        uint256 connectionId;
        address owner;
        uint256 lastActivity;
        uint256 jobCount;
        bool active;
    }

    address public immutable trustedSigner;
    uint256 public immutable maxPoolSize;
    uint256 public connectionCounter;
    uint256 public jobCounter;

    mapping(uint256 => PoolConnection) public connections;
    mapping(uint256 => ProcessingJob) public jobs;
    mapping(address => uint256[]) public userConnections;
    mapping(bytes32 => bool) public processedImages;
    mapping(bytes32 => bool) public usedSignatures;

    event ConnectionOpened(uint256 indexed connectionId, address indexed owner);
    event JobSubmitted(uint256 indexed jobId, uint256 indexed connectionId);
    event JobCompleted(uint256 indexed jobId, bytes32 resultHash);

    error InvalidSignature();
    error ConnectionInactive();
    error PoolFull();
    error Unauthorized();
    error JobAlreadyCompleted();
    error SignatureAlreadyUsed();
    error ArrayLengthMismatch();

    constructor(address _trustedSigner, uint256 _maxPoolSize) {
        trustedSigner = _trustedSigner;
        maxPoolSize = _maxPoolSize;
    }

    function openConnection(bytes calldata signature) external returns (uint256) {
        bytes32 messageHash = keccak256(abi.encodePacked(
            msg.sender,
            block.chainid,
            address(this),
            "OPEN_CONNECTION"
        ));

        _verifySignature(messageHash, signature);

        uint256 connId = ++connectionCounter;
        connections[connId] = PoolConnection({
            connectionId: connId,
            owner: msg.sender,
            lastActivity: block.timestamp,
            jobCount: 0,
            active: true
        });
        userConnections[msg.sender].push(connId);

        emit ConnectionOpened(connId, msg.sender);
        return connId;
    }

    function submitBatchJobs(
        uint256 connectionId,
        bytes32[] calldata imageHashes,
        uint8[] calldata filterTypes,
        uint256[] calldata priorities,
        uint256 nonce,
        bytes calldata signature
    ) external {
        PoolConnection storage conn = connections[connectionId];
        if (!conn.active) revert ConnectionInactive();
        if (conn.owner != msg.sender) revert Unauthorized();

        if (
            imageHashes.length != filterTypes.length ||
            imageHashes.length != priorities.length
        ) revert ArrayLengthMismatch();

        bytes32 batchHash = keccak256(abi.encodePacked(
            msg.sender,
            connectionId,
            keccak256(abi.encodePacked(imageHashes)),
            keccak256(abi.encodePacked(filterTypes)),
            keccak256(abi.encodePacked(priorities)),
            nonce
        ));

        _verifySignature(batchHash, signature);

        for (uint256 i = 0; i < imageHashes.length; i++) {
            uint256 jobId = ++jobCounter;
            jobs[jobId] = ProcessingJob({
                requester: msg.sender,
                imageHash: imageHashes[i],
                filterType: filterTypes[i],
                priority: priorities[i],
                timestamp: block.timestamp,
                completed: false
            });
            conn.jobCount++;
            emit JobSubmitted(jobId, connectionId);
        }

        conn.lastActivity = block.timestamp;
    }

    function completeJob(
        uint256 jobId,
        bytes32 resultHash,
        bytes calldata signature
    ) external {
        ProcessingJob storage job = jobs[jobId];
        if (job.completed) revert JobAlreadyCompleted();

        bytes32 completionHash = keccak256(abi.encodePacked(
            jobId,
            resultHash,
            job.imageHash,
            job.filterType
        ));

        _verifySignature(completionHash, signature);

        job.completed = true;
        processedImages[job.imageHash] = true;

        emit JobCompleted(jobId, resultHash);
    }

    function closeConnection(uint256 connectionId) external {
        PoolConnection storage conn = connections[connectionId];
        if (conn.owner != msg.sender) revert Unauthorized();
        conn.active = false;
    }

    function _verifySignature(bytes32 messageHash, bytes calldata signature) internal {
        bytes32 sigHash = keccak256(signature);
        if (usedSignatures[sigHash]) revert SignatureAlreadyUsed();

        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);

        if (recovered != trustedSigner) revert InvalidSignature();

        usedSignatures[sigHash] = true;
    }

    function getConnectionJobs(uint256 connectionId) external view returns (uint256) {
        return connections[connectionId].jobCount;
    }

    function isImageProcessed(bytes32 imageHash) external view returns (bool) {
        return processedImages[imageHash];
    }
}
